using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class AtelierReviewA {
 static double next;static List<string> checks=new List<string>();
 static AtelierReviewA(){EditorApplication.update+=Poll;}
 public static void Run(){EditorSceneManager.OpenScene(AtelierEditor.Scene);SessionState.SetBool("Atelier.ReviewA",true);SessionState.SetInt("Atelier.ReviewStep",0);checks.Clear();EditorApplication.EnterPlaymode();next=EditorApplication.timeSinceStartup+5;}
 static void Check(bool ok,string message){checks.Add((ok?"PASS ":"FAIL ")+message);File.WriteAllLines(AtelierEditor.Root+"/Reports/A-interaction-checks.txt",checks);if(!ok)throw new Exception(message);}
 static bool CanPoint(AtelierExperience x,AtelierControl c){var collider=c.GetComponentInChildren<Collider>();if(!collider)return false;var target=collider.bounds.center;var cam=x.engine.studioCamera;RaycastHit hit;return Physics.Raycast(new Ray(cam.transform.position,(target-cam.transform.position).normalized),out hit,150,~((1<<29)|(1<<30)|(1<<2)))&&hit.collider.GetComponentInParent<AtelierControl>()==c;}
 static void View(AtelierExperience x,Vector3 target,float distance,float yaw,float pitch){x.viewTarget=target;x.viewDistance=distance;x.viewYaw=yaw;x.viewPitch=pitch;}
 static void Capture(AtelierExperience x,string name){var cam=x.engine.studioCamera;var old=cam.targetTexture;var rt=new RenderTexture(1800,1200,24,RenderTextureFormat.ARGB32);cam.targetTexture=rt;cam.Render();var active=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1800,1200,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1800,1200),0,0);tex.Apply();File.WriteAllBytes(AtelierEditor.Root+"/Reports/"+name+".png",tex.EncodeToPNG());RenderTexture.active=active;cam.targetTexture=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}
 static void PartImage(AtelierExperience x,string key,string name,float yaw,float pitch,float distance){var p=x.assembly.pieces.First(v=>v.key==key);var go=UnityEngine.Object.Instantiate(p.prefab,new Vector3(0,3,5),Quaternion.identity);foreach(var tr in go.GetComponentsInChildren<Transform>(true))tr.gameObject.layer=31;foreach(var c in go.GetComponentsInChildren<Collider>(true))c.enabled=false;var cam=x.engine.studioCamera;var mask=cam.cullingMask;cam.cullingMask=1<<31;cam.transform.position=new Vector3(0,3,5)+Quaternion.Euler(-pitch,yaw,0)*Vector3.forward*distance;cam.transform.LookAt(new Vector3(0,3,5));Capture(x,name);cam.cullingMask=mask;UnityEngine.Object.DestroyImmediate(go);}
 static void Poll(){if(!SessionState.GetBool("Atelier.ReviewA",false)||!EditorApplication.isPlaying||EditorApplication.isCompiling)return;EditorApplication.QueuePlayerLoopUpdate();UnityEditorInternal.InternalEditorUtility.RepaintAllViews();if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+1;var x=UnityEngine.Object.FindObjectOfType<AtelierExperience>();if(!x||!x.Ready||!x.assembly.canvas||Time.frameCount<5)return;var w=x.assembly;int step=SessionState.GetInt("Atelier.ReviewStep",0);try{switch(step){
 case 0:Check(UnityEngine.Object.FindObjectsOfType<BoxCollider>().All(b=>b.size.x>0&&b.size.y>0&&b.size.z>0),"All click targets have valid positive bounds");Check(w.pieces.Length==45,"45 assembly groups after independent lamps");Check(w.pieces.Count(p=>p.key=="rheadlamp"||p.key=="lheadlamp")==2,"Two distinct lamp pieces");Check(!w.Compatible(Array.FindIndex(w.pieces,p=>p.key=="rheadlamp"),Array.FindIndex(w.pieces,p=>p.key=="lheadlamp")),"Left and right lamp sockets are distinct");x.Activate(AtelierAction.Assembly);Check(!x.HoldReset(2)&&w.Complete,"Closed guard prevents reset");x.Activate(AtelierAction.ResetGuard);x.Activate(AtelierAction.Assembly);Check(!x.HoldReset(.4f)&&w.Complete,"Short hold does not reset");x.CancelReset();Check(w.Complete,"Cancelled reset preserves build");x.Activate(AtelierAction.Assembly);Check(x.HoldReset(1.3f)&&w.InstalledCount==0,"Lift guard then hold resets assembly");View(x,new Vector3(5.25f,.55f,3.55f),6.9f,12,48);break;
 case 1:Check(x.PageCount==6&&x.pageCounter.text=="01 / 06","Dynamic six page counter");Check(x.trayModels.Count(g=>g)==8,"Eight parts seated in tray");var nav=UnityEngine.Object.FindObjectsOfType<AtelierControl>();Check(nav.First(c=>c.action==AtelierAction.TrayPrevious).transform.position.x>nav.First(c=>c.action==AtelierAction.TrayNext).transform.position.x,"Previous paddle is on the viewer left");x.Activate(AtelierAction.TrayNext);Check(x.trayPage==1,"Next paddle advances one page");Check(nav.Where(c=>c.action==AtelierAction.TrayPrevious||c.action==AtelierAction.TrayNext||c.action==AtelierAction.Category).All(c=>CanPoint(x,c)),"All tray navigation controls can be pointed at from player view");break;
 case 2:Check(x.trayRoot.GetComponentsInChildren<Transform>().Count(t=>t.name.StartsWith("TrayPreview_"))==8,"No duplicate preview after deferred destruction");x.Activate(AtelierAction.TrayPrevious);x.Activate(AtelierAction.Category,4);Check(x.trayCategory==3&&x.FilteredParts().All(i=>w.pieces[i].category==2),"Body selector filters only body parts");break;
 case 3:Capture(x,"A-01-parts-tray");int id=x.FilteredParts()[0];x.Activate(AtelierAction.TrayPart,id);Check(w.token&&w.selected==id,"Direct tray click creates the requested component");break;
 case 4:Check(w.token&&w.dragging,"Grab survives the following frame");w.MoveGrab(w.Socket);w.ReleaseGrab();w.LeaveInSpace();Check(w.pieces[x.FilteredParts()[0]].installed,"Tray part installs normally");x.Activate(AtelierAction.Category,1);x.trayPage=x.PageCount-1;x.RefreshTray();break;
 case 5:Check(x.pageCounter.text=="06 / 06","Last page counter");Check(x.trayModels.Count(g=>g)==5,"Last page holds five remaining bays");Capture(x,"A-02-two-lamps");x.SetThrottle(0);View(x,new Vector3(-6.25f,.55f,3.55f),6.7f,9,30);break;
 case 6:Check(UnityEngine.Object.FindObjectsOfType<AtelierControl>().Where(c=>c.action==AtelierAction.Throttle||c.action==AtelierAction.Brake||c.action==AtelierAction.Reverse||c.action==AtelierAction.Lights||c.action==AtelierAction.Whistle||c.action==AtelierAction.Cutaway||c.action==AtelierAction.Observation||c.action==AtelierAction.ResetGuard).All(c=>CanPoint(x,c)),"Driving levers and auxiliary switches are reachable by pointer");Capture(x,"A-03-driving-desk");w.AssembleForDisplay();x.SetDirection(0);x.SetThrottle(1);Check(!x.engine.running&&x.throttle==0,"Neutral detent cannot power wheels");x.SetDirection(-1);x.SetThrottle(.3f);break;
 case 7:Check(x.engine.running&&x.engine.direction==-1,"Reverse detent drives reverse");x.SetDirection(1);Check(!x.engine.running&&x.throttle==0,"Direction change brakes before engaging");int li=Array.FindIndex(w.pieces,p=>p.key=="lheadlamp");w.TakeInstalled(li);w.MoveGrab(new Vector3(8,4,5));w.ReleaseGrab();w.LeaveInSpace();break;
 case 8:Check(x.presentation.headlight.enabled&&!x.secondLamp.gameObject.activeInHierarchy,"Removing left lamp leaves right lamp lit");w.AssembleForDisplay();PartImage(x,"firebox","A-04-firebox-shell",73,21,3.6f);PartImage(x,"firebox","A-05-firebox-backhead",-112,14,3.6f);PartImage(x,"boiler","A-06-boiler-bands",63,25,6);PartImage(x,"rearbeam","A-07-buffer-brackets",72,22,4);PartImage(x,"exhaust","A-08-exhaust-junction",63,12,3.2f);break;
 case 9:foreach(var p in w.pieces)p.installed=false;w.ResetPuzzle();x.RefreshTray();View(x,new Vector3(.55f,1.6f,0),5,36,52);break;
 case 10:Capture(x,"A-09-saddle-interfaces");w.AssembleForDisplay();x.SetView(0);x.assembly.effects.fireEnabled=true;break;
 case 11:Capture(x,"A-10-workbench");x.SetThrottle(.65f);if(!x.guardOpen)x.Activate(AtelierAction.ResetGuard);View(x,new Vector3(-6.25f,.55f,3.55f),6.7f,9,30);next=EditorApplication.timeSinceStartup+2;break;
 case 12:Check(x.floatingStatus.parent==x.statusDock&&Quaternion.Angle(x.floatingStatus.localRotation,Quaternion.identity)<.1f,"Embedded readout remains aligned with its physical screen");Check(x.pressure>0&&x.pressureText.text.Contains("bar"),"Inset pressure display updates while train runs");Check(x.resetButton.enabled&&CanPoint(x,x.resetButton.GetComponentInParent<AtelierControl>()),"Lifted safety lid exposes the actual reset button");Capture(x,"A-11-operated-console");x.Activate(AtelierAction.Brake);x.Activate(AtelierAction.ResetGuard);View(x,new Vector3(-4.86f,.73f,3.50f),2.8f,25,24);break;
 case 13:Capture(x,"A-12-throttle-detail");x.SetThrottle(0);View(x,new Vector3(-7.53f,.60f,3.47f),2.8f,-20,24);break;
 case 14:Capture(x,"A-13-reverser-detail");View(x,new Vector3(-6.25f,.55f,3.55f),6.7f,9,30);break;
 case 15:Capture(x,"A-14-final-console");File.WriteAllText(AtelierEditor.Root+"/Reports/A-review-complete.txt","PASS "+checks.Count+" interaction checks and 14 review images");SessionState.SetBool("Atelier.ReviewA",false);return;
 }SessionState.SetInt("Atelier.ReviewStep",step+1);}catch(Exception e){SessionState.SetBool("Atelier.ReviewA",false);File.WriteAllText(AtelierEditor.Root+"/Reports/A-review-error.txt",e.ToString());Debug.LogException(e);}}
}
